// Linux (SSH) – estado do sistema.
// Só leitura: versão, carga, memória e discos.

fn detect(device, params) {
    let os = parse_kv(device.run("cat /etc/os-release 2>/dev/null"), "=");
    #{
        firmware: os.VERSION_ID,
        os: os.PRETTY_NAME,
        kernel: trimmed(device.run("uname -r")),
        arch: trimmed(device.run("uname -m"))
    }
}

fn system_status(device, params) {
    let uptime = words(device.run("cat /proc/uptime"));
    let load = words(device.run("cat /proc/loadavg"));
    let mem = parse_kv(device.run("cat /proc/meminfo"), ":");
    #{
        uptime_seconds: uptime[0],
        load_1m: load[0],
        load_5m: load[1],
        load_15m: load[2],
        mem_total: mem.MemTotal,
        mem_available: mem.MemAvailable
    }
}

fn disk_usage(device, params) {
    let rows = [];
    let all = lines(device.run("df -P"));
    for i in 1..all.len() {
        let cols = words(all[i]);
        if cols.len() >= 6 {
            rows.push(#{
                filesystem: cols[0],
                size_kb: cols[1],
                used_kb: cols[2],
                available_kb: cols[3],
                used: cols[4],
                mount: cols[5]
            });
        }
    }
    rows
}
